# Harmonia OLED True Black
# generated by harmonia-terminal, do not edit

& {
  $e = [char]27

  try {
    if (Get-Module PSReadLine) {
      $rlVersion = (Get-Module PSReadLine).Version
      $colors = @{
        Default = "$e[39m"
        Comment = "$e[38;2;125;130;141m"
        Keyword = "$e[38;2;166;142;219m"
        String = "$e[38;2;152;209;184m"
        Number = "$e[38;2;225;179;122m"
        Operator = "$e[38;2;187;185;200m"
        Variable = "$e[38;2;136;197;194m"
        Parameter = "$e[38;2;167;222;174m"
        Command = "$e[38;2;91;155;213m"
        Type = "$e[38;2;156;192;255m"
        Member = "$e[38;2;200;200;210m"
        Emphasis = "$e[38;2;91;155;213m"
        Error = "$e[38;2;232;132;138m"
        ContinuationPrompt = "$e[38;2;110;115;143m"
        Selection = "$e[39;48;2;17;30;43m"
      }
      if ($rlVersion -ge [version]'2.1') {
        $colors.InlinePrediction = "$e[38;2;125;130;141m"
      }
      if ($rlVersion -ge [version]'2.2') {
        $colors.ListPrediction = "$e[38;2;91;155;213m"
        $colors.ListPredictionSelected = "$e[48;2;12;13;18m"
      }
      if ($rlVersion -ge [version]'2.3') {
        $colors.ListPredictionTooltip = "$e[38;2;125;130;141m"
      }
      Set-PSReadLineOption -Colors $colors -ErrorAction Stop
    }
  } catch {}

  try {
    if ($PSVersionTable.PSVersion -ge [version]'7.2') {
      $PSStyle.Formatting.TableHeader = "$e[1;38;2;156;192;255m"
      $PSStyle.Formatting.FormatAccent = "$e[1;38;2;156;192;255m"
      $PSStyle.Formatting.CustomTableHeaderLabel = "$e[3;38;2;156;192;255m"
      $PSStyle.Formatting.Error = "$e[38;2;232;132;138m"
      $PSStyle.Formatting.ErrorAccent = "$e[1;38;2;232;132;138m"
      $PSStyle.Formatting.Warning = "$e[38;2;225;179;122m"
      $PSStyle.Formatting.Verbose = "$e[38;2;91;155;213m"
      $PSStyle.Formatting.Debug = "$e[38;2;125;130;141m"
      $formatting = $PSStyle.Formatting.PSObject.Properties
      if ($formatting['FeedbackName']) { $PSStyle.Formatting.FeedbackName = "$e[38;2;91;155;213m" }
      if ($formatting['FeedbackText']) { $PSStyle.Formatting.FeedbackText = "$e[39m" }
      if ($formatting['FeedbackAction']) { $PSStyle.Formatting.FeedbackAction = "$e[38;2;152;209;184m" }
      $PSStyle.Progress.Style = "$e[38;2;0;0;0;48;2;91;155;213m"
      $PSStyle.FileInfo.Directory = "$e[1;38;2;91;155;213m"
      $PSStyle.FileInfo.SymbolicLink = "$e[38;2;150;215;212m"
      $PSStyle.FileInfo.Executable = "$e[38;2;152;209;184m"
      $PSStyle.FileInfo.Extension['.zip'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.tgz'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.gz'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.tar'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.nupkg'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.cab'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.7z'] = "$e[38;2;225;179;122m"
      $PSStyle.FileInfo.Extension['.ps1'] = "$e[38;2;166;142;219m"
      $PSStyle.FileInfo.Extension['.psd1'] = "$e[38;2;166;142;219m"
      $PSStyle.FileInfo.Extension['.psm1'] = "$e[38;2;166;142;219m"
      $PSStyle.FileInfo.Extension['.ps1xml'] = "$e[38;2;166;142;219m"
      $PSStyle.FileInfo.Extension['.js'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.jse'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbs'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.vbe'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsf'] = "$e[39m"
      $PSStyle.FileInfo.Extension['.wsh'] = "$e[39m"
      $formatFile = Join-Path $PSScriptRoot 'harmonia.format.ps1xml'
      if (Test-Path $formatFile) { Update-FormatData -PrependPath $formatFile }
    }
  } catch {}
}
